def find_close(src, start):
    # given index of '{', find matching '}' handling strings/comments roughly
    depth = 0
    i = start
    n = len(src)
    while i < n:
        c = src[i]
        if c == '{': depth += 1
        elif c == '}':
            depth -= 1
            if depth == 0: return i
        elif c == '"' or c == "'":
            q = c; i += 1
            while i < n and src[i] != q:
                if src[i] == '\\': i += 1
                i += 1
        elif c == '/' and i+1 < n and src[i+1] == '*':
            j = src.find('*/', i+2)
            i = j if j >= 0 else n-1
        elif c == '/' and i+1 < n and src[i+1] == '/':
            j = src.find('\n', i)
            i = j if j >= 0 else n-1
        i += 1
    return n-1

def funcbody(src, name):
    # find function definitions 'name(' where preceded by non-ident char and followed eventually by '{'
    out = []
    for m in re.finditer(r'(?<![\w.>])' + re.escape(name) + r'\s*\(', src):
        i = m.end()
        # skip params to ')'
        depth = 1
        while i < len(src) and depth:
